<script setup lang="ts">defineProps<{open:boolean;theme:string}>();defineEmits<{close:[];theme:[value:string];unpair:[]}>();</script>
<template><div v-if="open" class="viewer-backdrop" @click.self="$emit('close')"><section class="settings-surface"><header><div><small>设备与外观</small><h2>设置</h2></div><button class="icon-button" @click="$emit('close')">×</button></header><label>主题<select :value="theme" @change="$emit('theme',($event.target as HTMLSelectElement).value)"><option value="system">跟随系统</option><option value="light">浅色</option><option value="dark">深色</option></select></label><div class="settings-row"><div><strong>已配对设备</strong><small>凭据仅用于本机连接，界面不会显示令牌。</small></div><button class="danger-button" @click="$emit('unpair')">解除配对</button></div><div class="settings-row"><div><strong>Codex-only</strong><small>此客户端不提供其他 provider 或终端工具箱。</small></div></div></section></div></template>
